package kr.ac.kdu.focurve;
import org.springframework.stereotype.Component;import org.springframework.context.annotation.Profile;import org.springframework.scheduling.annotation.EnableScheduling;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.beans.factory.ObjectProvider;import org.springframework.core.env.Environment;import org.springframework.mail.javamail.*;import org.springframework.mail.SimpleMailMessage;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import java.time.Instant;import java.sql.Timestamp;
import static kr.ac.kdu.focurve.MemberAuth.*;
@Profile("member-runtime | local-integration") @Component @EnableScheduling
class MailOutbox {
 final MemberAuth a;final ObjectProvider<JavaMailSender> senders;final Environment env;final TransactionTemplate tx;
 MailOutbox(MemberAuth a,ObjectProvider<JavaMailSender> senders,Environment env,PlatformTransactionManager tm){this.a=a;this.senders=senders;this.env=env;this.tx=new TransactionTemplate(tm);}
 boolean configured(){return env.getProperty("member.mail.external-enabled",Boolean.class,false)&&!env.getProperty("member.mail.from","").isBlank()&&senders.getIfAvailable()!=null;}
 @Scheduled(fixedDelay=5000) void deliver(){if(!configured())return;for(int n=0;n<10;n++){Boolean consumed=tx.execute(t->{var row=a.one("SELECT m.*,c.expires_at,c.consumed_at FROM auth_mail_outbox m JOIN auth_challenges c ON m.challenge_id=c.id WHERE m.status='PENDING' AND (m.retry_after IS NULL OR m.retry_after<=CURRENT_TIMESTAMP(3)) ORDER BY m.created_at LIMIT 1 FOR UPDATE SKIP LOCKED");if(row==null)return false;if(!future(row.get("expires_at"))||row.get("consumed_at")!=null){a.db.update("UPDATE auth_mail_outbox SET status='EXPIRED' WHERE id=?",row.get("id"));return true;}int attempts=((Number)row.get("attempts")).intValue()+1;try{JavaMailSender sender=senders.getObject();if(sender instanceof JavaMailSenderImpl impl){impl.getJavaMailProperties().setProperty("mail.smtp.ssl.checkserveridentity","true");if(!Boolean.parseBoolean(impl.getJavaMailProperties().getProperty("mail.smtp.ssl.enable","false"))){impl.getJavaMailProperties().setProperty("mail.smtp.starttls.enable","true");impl.getJavaMailProperties().setProperty("mail.smtp.starttls.required","true");}impl.getJavaMailProperties().setProperty("mail.smtp.connectiontimeout","10000");impl.getJavaMailProperties().setProperty("mail.smtp.timeout","10000");impl.getJavaMailProperties().setProperty("mail.smtp.writetimeout","10000");}SimpleMailMessage message=message(env.getProperty("member.mail.from"),row.get("recipient").toString(),row.get("kind").toString(),a.crypt(row.get("token_cipher").toString(),false),a.origin);sender.send(message);a.db.update("UPDATE auth_mail_outbox SET status='SENT',sent_at=?,attempts=?,last_error_code=NULL WHERE id=?",now(),attempts,row.get("id"));}catch(Exception failure){a.db.update("UPDATE auth_mail_outbox SET status=?,attempts=?,retry_after=?,last_error_code='MAIL_PROVIDER_FAILED' WHERE id=?",attempts>=5?"FAILED":"PENDING",attempts,Timestamp.from(Instant.now().plusSeconds(Math.min(30,1L<<attempts))),row.get("id"));}return true;});if(!Boolean.TRUE.equals(consumed))break;}}
 static SimpleMailMessage message(String from,String to,String kind,String token,String origin){SimpleMailMessage m=new SimpleMailMessage();m.setFrom(from);m.setTo(to);m.setSubject(kind.equals("EMAIL_VERIFY")?"FOCURVE 이메일 인증":"FOCURVE 비밀번호 재설정");m.setText("다음 FOCURVE 링크를 열어 요청을 확인해 주세요.\n"+origin.replaceAll("/+$","")+"/#"+(kind.equals("EMAIL_VERIFY")?"verify":"reset")+"?token="+java.net.URLEncoder.encode(token,java.nio.charset.StandardCharsets.UTF_8)+"\n요청하지 않았다면 사용하지 마세요.");return m;}
}
